31: // ── sizing ─────────────────────────────────────────────────────
32: function resize() {
33:   const w = Math.max(320, Math.round(window.innerWidth));
34:   const h = Math.max(320, Math.round(window.innerHeight));
35:   dpr = Math.min(2, window.devicePixelRatio || 1);
36:   viewW = w;
37:   viewH = h;
38:   canvas.width = Math.round(w * dpr);
39:   canvas.height = Math.round(h * dpr);
40:   canvas.style.width = w + 'px';
41:   canvas.style.height = h + 'px';
42:   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
43:   ctx.imageSmoothingEnabled = true;
44: }
