46: // ── scene loop ─────────────────────────────────────────────────
47: function frame(now) {
48:   const dt = Math.min(48, Math.max(0, now - (lastFrame || now)));
49:   lastFrame = now;
50:   ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
51:   if (mode === 'world') {
52:     if (battleState.active) {
53:       renderBattle(ctx, viewW, viewH, battleState, now);
54:     } else {
55:       updateWorld(dt, viewW, viewH);
56:       renderWorldScene(ctx, viewW, viewH, now);
57:     }
58:   } else {
59:     // Title backdrop remains behind creation and ending screens.
60:     renderTitle(ctx, viewW, viewH, now);
61:   }
62:   requestAnimationFrame(frame);
63: }
