192:     state.chapter = 'Epilogue';
193:     showEnding(buildEndingData(state.ending));
194:     return;
195:   }
196:   const z = ZONES[state.zone] ? state.zone : 'hearthfall';
197:   beginWorld(z, state.pos?.x, state.pos?.y);
