213: // ── endings ────────────────────────────────────────────────────
214: function showEnding(data) {
215:   if (!data) return;
216:   mode = 'ending';
217:   world.paused = true;
218:   hideHud(true);
219:   $('#ending-kicker').textContent = data.kicker || 'EPILOGUE';
220:   $('#ending-title').textContent = data.title || 'Dawnforge';
221:   $('#ending-body').innerHTML = data.body || '';
222:   $('#ending-choices').innerHTML = (data.choices || [])
223:     .map((c) => `<div><b>${escapeHtml(c.label)}</b><span>${escapeHtml(c.value)}</span></div>`)
224:     .join('');
225:   showScreen('screen-ending');
226:   audio.setScene('ending');
227:   updateContinueMeta();
228:   saveGame(true);
