231: // ── hooks ──────────────────────────────────────────────────────
232: function wireHooks() {
233:   hooks.newGame = ({ name, classId, origin, palette, bonus }) => {
234:     createHero({ name, classId, origin, palette, extra: { bonus } });
235:     restoreParty(true);
236:     state.started = true;
237:     state.act = 0;
238:     state.chapter = 'Prologue';
239:     saveGame(true);
240:     beginWorld('hearthfall', 15, 14);
241:   };
242: 
243:   hooks.continueGame = continueGame;
244:   hooks.returnToTitle = returnToTitle;
245:   hooks.openMenu = (tab = 'status') => openMenu(tab);
246:   hooks.openWorldMap = () => openMenu('map');
247:   hooks.openShop = (id) => openShop(id);
248:   hooks.save = (auto = true) => saveGame(auto);
249:   hooks.setPaused = (v) => setPaused(v);
250:   hooks.setDifficulty = (d) => setDifficulty(d);
251: 
252:   hooks.startBattle = (opts) => startBattle(opts);
253:   hooks.respawn = () => {
254:     respawnPlayer();
255:     updateHud(world.zone);
256:     saveGame(true);
257:   };
258: 
259:   hooks.travel = async (zoneId, x, y, opts = {}) => {
260:     if (!ZONES[zoneId]) return;
261:     world.paused = true;
262:     audio.sfx('portal');
263:     await fade(true, 280);
264:     enterZone(zoneId, x, y);
265:     updateHud(world.zone);
266:     await fade(false, 380);
267:     world.paused = !!opts.keepPaused;
268:     saveGame(true);
269:   };
270: 
271:   hooks.endGame = (data) => showEnding(data);
272: }
273: 
274: // ── boot ───────────────────────────────────────────────────────
275: function boot() {
276:   if (booted) return;
277:   booted = true;
278:   resize();
279:   touchModeOn();
280:   initWorld();
281:   initCreation();
282:   initMenu();
283:   initShop();
284:   initTitle();
285:   wireHooks();
286:   updateContinueMeta();
287:   updateSoundButton();
288:   audio.setEnabled(currentSound());
289:   audio.setScene('title');
290: 
291:   // Audio contexts require a gesture. The first one also starts the title theme.
292:   const wake = () => {
293:     audio.init();
294:     audio.setEnabled(currentSound());
295:     if (mode === 'title' || mode === 'create') audio.setScene('title');
296:     document.removeEventListener('pointerdown', wake);
297:     document.removeEventListener('keydown', wake);
298:   };
299:   document.addEventListener('pointerdown', wake, { passive: true });
300:   document.addEventListener('keydown', wake);
301: 
302:   window.addEventListener('beforeunload', () => {
303:     if (state.started && !state.ending) saveGame(true);
304:   });
305: 
306:   requestAnimationFrame((now) => { lastFrame = now; frame(now); });
307: }
308: 
309: boot();

