66: export const DIFFICULTY = {
67:   story: { name: 'Story', enemyHp: .82, enemyDmg: .72, xp: 1.15, desc: 'For the story. Enemies hit softly.' },
68:   balanced: { name: 'Balanced', enemyHp: 1, enemyDmg: 1, xp: 1, desc: 'A fair fight, if you use your skills.' },
