76: export function statBlock(member) {
77:   const cls = CLASSES[member.classId];
78:   const lv = Math.max(1, member.level);
79:   const g = cls.grow, b = cls.base;
80:   const s = {
81:     hp: b.hp + g.hp * (lv - 1),
82:     mp: b.mp + g.mp * (lv - 1),
83:     atk: b.atk + g.atk * (lv - 1),
84:     def: b.def + g.def * (lv - 1),
85:     mag: b.mag + g.mag * (lv - 1),
86:     res: b.res + g.res * (lv - 1),
87:     agi: b.agi + g.agi * (lv - 1),
88:     luck: b.luck + g.luck * (lv - 1),
89:   };
90:   const pct = { hp: 0, mp: 0 };
91:   const eleRes = { fire: 0, frost: 0, storm: 0, nature: 0, shadow: 0, earth: 0, water: 0, holy: 0 };
92:   const extras = { crit: 0, evade: 0, lifesteal: 0, counter: 0, mpRegen: 0, stormBoost: 0, reviveOnce: false };
93:   const tree = cls.tree;
94:   for (const node of tree) {
95:     if (!member.learned?.includes(node.id)) continue;
96:     const sk = SKILLS[node.id];
97:     if (!sk?.passive) continue;
98:     if (sk.mods) for (const [k, v] of Object.entries(sk.mods)) {
99:       if (k === 'hpPct') pct.hp += v;
100:       else if (k === 'mpPct') pct.mp += v;
101:       else if (k === 'crit') extras.crit += v;
102:       else if (k === 'evade') extras.evade += v;
103:       else if (k === 'fireRes') eleRes.fire += v;
104:       else if (k === 'lifesteal') extras.lifesteal += v;
105:       else if (s[k] !== undefined) s[k] += v;
106:     }
107:     if (sk.special === 'reviveOnce') extras.reviveOnce = true;
108:     if (sk.special === 'counter') extras.counter += .35;
109:     if (sk.special === 'counter25') extras.counter += .25;
110:     if (sk.special === 'lifesteal') extras.lifesteal += .18;
111:     if (sk.special === 'mpRegen') extras.mpRegen += 4;
112:     if (sk.special === 'mpRegen2') extras.mpRegen += 3;
113:     if (sk.special === 'stormBoost') extras.stormBoost += .2;
114:   }
115:   if (member.id === 'hero') {
116:     const o = ORIGINS[member.origin || state.heroOrigin];
117:     if (o?.bonuses) {
118:       for (const [k, v] of Object.entries(o.bonuses)) {
119:         if (k === 'hpPct') pct.hp += v;
120:         else if (s[k] !== undefined) s[k] += v;
121:       }
122:     }
123:   }
124:   if (member.bonus) for (const [k, v] of Object.entries(member.bonus)) { if (s[k] !== undefined) s[k] += v; }
125:   // equipment
126:   for (const slot of ['weapon', 'charm']) {
127:     const gid = member.gear?.[slot];
128:     const gi = gid && ITEMS[gid];
129:     if (gi?.stats) for (const [k, v] of Object.entries(gi.stats)) {
130:       if (k === 'hp' || k === 'mp') s[k] += v;
131:       else if (s[k] !== undefined) s[k] += v;
132:     }
133:   }
134:   s.hp = Math.round(s.hp * (1 + pct.hp));
135:   s.mp = Math.round(s.mp * (1 + pct.mp));
136:   for (const k of Object.keys(s)) s[k] = Math.round(s[k]);
137:   s.maxHp = s.hp;
138:   s.maxMp = s.mp;
139:   s.crit = .05 + s.luck * .004 + extras.crit;
140:   s.evade = Math.min(.35, s.agi * .002 + extras.evade);
141:   s.lifesteal = Math.min(.5, extras.lifesteal);
142:   s.counter = Math.min(.6, extras.counter);
143:   s.mpRegen = extras.mpRegen;
144:   s.stormBoost = extras.stormBoost;
145:   s.reviveOnce = extras.reviveOnce;
146:   s.eleRes = eleRes;
147:   return s;
148: }
