150: export function makeMember({ id, name, classId, palette = 0, level = 1, origin = null, auto = false }) {
151:   const m = {
152:     id, name, classId, palette, level,
153:     xp: 0, sp: Math.max(0, level - 1 + (auto ? 0 : 1)),
154:     learned: [...CLASSES[classId].start],
155:     gear: { weapon: null, charm: null },
156:     origin: origin || null,
157:     joined: true,
158:   };
159:   if (id === 'hero') m.origin = origin || state.heroOrigin;
160:   const st = statBlock(m);
161:   m.hp = st.maxHp;
162:   m.mp = st.maxMp;
163:   m.sp = Math.max(1, level - 1 + 1);
164:   if (auto) {
165:     m.sp = Math.max(1, level - 1 + 1);
166:     autoLearn(m);
167:   }
168:   return m;
169: }
