171: export function hero() { return state.party.find((m) => m.id === 'hero'); }
172: export function memberById(id) { return state.party.find((m) => m.id === id); }
173: export function fullStats(m) { return statBlock(m); }
174: 
175: export function syncVitals(m, oldStats = null) {
176:   const st = statBlock(m);
177:   if (oldStats) {
178:     const dHp = st.maxHp - oldStats.maxHp;
179:     const dMp = st.maxMp - oldStats.maxMp;
180:     m.hp = Math.max(1, Math.min(st.maxHp, m.hp + Math.max(0, dHp)));
181:     m.mp = Math.max(0, Math.min(st.maxMp, m.mp + Math.max(0, dMp)));
182:   } else {
183:     m.hp = Math.min(m.hp ?? st.maxHp, st.maxHp);
184:     m.mp = Math.min(m.mp ?? st.maxMp, st.maxMp);
185:   }
186:   if (m.hp <= 0) m.hp = 0;
187:   return st;
188: }
189: 
190: export function restoreParty(full = true) {
191:   for (const m of state.party) {
192:     const st = statBlock(m);
193:     if (full) { m.hp = st.maxHp; m.mp = st.maxMp; }
194:     else { m.hp = Math.min(st.maxHp, m.hp + Math.round(st.maxHp * .5)); m.mp = Math.min(st.maxMp, m.mp + Math.round(st.maxMp * .5)); }
195:   }
196: }
