198: export function addXp(m, amount) {
199:   const levels = [];
200:   m.xp += amount;
201:   while (m.xp >= xpNeed(m.level)) {
202:     m.xp -= xpNeed(m.level);
203:     m.level++;
204:     m.sp += 1;
205:     if (m.level % 5 === 0) m.sp += 1;
206:     levels.push(m.level);
207:     const st = statBlock(m);
208:     m.hp = st.maxHp;
209:     m.mp = st.maxMp;
210:     if (m.id !== 'hero') autoLearn(m);
211:   }
212:   return levels;
213: }
