215: export function learnNode(member, nodeId) {
216:   const cls = CLASSES[member.classId];
217:   const node = cls.tree.find((n) => n.id === nodeId);
218:   if (!node || member.learned.includes(nodeId) || member.sp < node.sp) return false;
219:   const reqs = node.req || [];
220:   if (!reqs.every((r) => member.learned.includes(r))) return false;
221:   member.sp -= node.sp;
222:   member.learned.push(nodeId);
223:   syncVitals(member);
224:   return true;
225: }
226: 
227: export function availableNodes(member) {
228:   const cls = CLASSES[member.classId];
229:   return cls.tree.filter((n) => !member.learned.includes(n.id) && (n.req || []).every((r) => member.learned.includes(r)));
230: }
231: 
232: export function autoLearn(member) {
233:   let guard = 0;
234:   while (member.sp > 0 && guard++ < 30) {
235:     const avail = availableNodes(member)
236:       .filter((n) => n.sp <= member.sp)
237:       .sort((a, b) => a.sp - b.sp || a.tier - b.tier || a.col - b.col);
238:     if (!avail.length) break;
239:     learnNode(member, avail[0].id);
240:   }
241: }
