248: export function joinCompanion(id) {
249:   if (state.party.some((m) => m.id === id)) return false;
250:   const c = COMPANIONS[id];
251:   if (!c) return false;
252:   if (state.party.length >= 4) return false;
253:   const member = makeMember({
254:     id, name: c.name, classId: c.classId, palette: c.palette,
255:     level: companionLevel(), auto: true,
256:   });
257:   member.title = c.title;
258:   member.bio = c.bio;
259:   const st = statBlock(member);
260:   member.hp = st.maxHp; member.mp = st.maxMp;
261:   state.party.push(member);
