224: function findPath(start, goal, maxNodes = 900) {
225:   if (start.x === goal.x && start.y === goal.y) return [];
226:   const key = (x, y) => x + ',' + y;
227:   const q = [{ x: start.x, y: start.y, p: null }];
228:   const seen = new Set([key(start.x, start.y)]);
229:   let head = 0;
230:   let found = null;
231:   while (head < q.length && q.length < maxNodes) {
232:     const cur = q[head++];
233:     if (cur.x === goal.x && cur.y === goal.y) { found = cur; break; }
234:     for (const [dx, dy] of Object.values(DIRS)) {
235:       const nx = cur.x + dx, ny = cur.y + dy;
236:       const k = key(nx, ny);
237:       if (seen.has(k) || !isWalkable(nx, ny)) continue;
238:       seen.add(k);
239:       q.push({ x: nx, y: ny, p: cur });
240:     }
241:   }
242:   if (!found) return null;
243:   const path = [];
244:   let n = found;
245:   while (n && n.p) { path.unshift({ x: n.x, y: n.y }); n = n.p; }
246:   return path;
247: }
