97: async function exec(cmd, ctx) {
98:   if (!cmd || typeof cmd !== 'object') return undefined;
99:   switch (cmd.t) {
100:     case 'say':
101:       if (cmd.who && cmd.text) await say(cmd.who, cmd.text, { portrait: cmd.portrait });
102:       return undefined;
103:     case 'choice':
104:       return await choice(cmd.options || []);
105:     case 'flag':
106:       state.flags[cmd.key] = cmd.value;
107:       return cmd.value;
108:     case 'give': {
109:       const it = ITEMS[cmd.item];
110:       if (!it) return false;
111:       if (it.type === 'gear') addGear(cmd.item); else addItem(cmd.item, cmd.n || 1);
112:       toast(`${it.name}${cmd.n > 1 ? ' ×' + cmd.n : ''} obtained.`, it.icon || '❖');
113:       return true;
114:     }
115:     case 'take':
116:       removeItem(cmd.item, cmd.n || 1);
117:       return true;
118:     case 'gear':
119:       addGear(cmd.item);
120:       toast(`${ITEMS[cmd.item]?.name || cmd.item} obtained.`, ITEMS[cmd.item]?.icon || '⚔');
121:       return true;
122:     case 'gold':
123:       if (cmd.n >= 0) { addGold(cmd.n); toast(`+${cmd.n} gold`, '◈'); }
124:       else addGold(cmd.n);
125:       syncHud();
126:       return true;
127:     case 'join': {
128:       if (hasMember(cmd.id)) return { already: true };
129:       const ok = joinCompanion(cmd.id);
130:       if (ok) {
131:         const m = state.party[state.party.length - 1];
132:         toast(`${m.name} joins the party.`, '✦', 3600);
133:         audio.sfx('levelup');
134:         syncHud();
135:       } else {
136:         toast('Your party is full.', '·');
137:       }
138:       return { ok };
139:     }
140:     case 'battle': {
141:       const res = await startBattle({
142:         zone: currentZone(),
143:         enemies: cmd.enemies || [],
144:         boss: !!cmd.boss,
145:         bossName: cmd.bossName || null,
146:         canFlee: cmd.canFlee !== false,
147:       });
148:       if (res?.defeat) {
149:         await fade(true, 320);
150:         toast('The crystal pulls you back from the dark.', '✦', 3200);
151:         restoreParty(true);
152:         hooks.respawn?.();
153:         await fade(false, 440);
154:         return { __abort: true, defeat: true };
155:       }
156:       syncHud();
157:       saveGame(true);
158:       return res || {};
159:     }
160:     case 'shop':
161:       await (hooks.openShop ? hooks.openShop(cmd.id) : openShop(cmd.id));
162:       return true;
163:     case 'heal':
164:       restoreParty(true);
165:       syncHud();
166:       toast('The party is fully restored.', '❖');
167:       return true;
168:     case 'rest': {
169:       restoreParty(true);
170:       state.time = .24;
171:       if (cmd.checkpoint) state.flags.lastCrystal = { ...cmd.checkpoint };
172:       syncHud();
173:       saveGame(true);
174:       toast('You rest. Wounds close; the road waits.', '☾');
175:       return true;
176:     }
177:     case 'toast':
178:       toast(cmd.text, cmd.icon || '✦', cmd.ms || 3000);
179:       return true;
180:     case 'cinematic':
181:       await cinematic(cmd.lines || [], cmd.opts || {});
182:       return true;
183:     case 'modal':
184:       return await modal(cmd);
185:     case 'wait':
186:       await sleep(cmd.ms || 300);
187:       return true;
188:     case 'music':
189:       audio.setScene(cmd.name || 'explore');
190:       return true;
191:     case 'sfx':
192:       audio.sfx(cmd.name || 'click');
193:       return true;
194:     case 'xp': {
195:       const levels = [];
196:       for (const m of state.party) {
197:         const gained = addXp(m, cmd.n || 0);
198:         if (gained.length) levels.push(`${m.name} reached level ${m.level}`);
199:       }
200:       for (const l of levels) toast(l, '✧', 3600);
201:       syncHud();
202:       return true;
203:     }
204:     case 'sp': {
205:       const h = heroMember();
206:       if (h) h.sp += cmd.n || 1;
207:       toast(`+${cmd.n || 1} skill point${(cmd.n || 1) === 1 ? '' : 's'}.`, '✦');
208:       syncHud();
209:       return true;
210:     }
211:     case 'quest':
212:       if (cmd.status === 'active') startQuest(cmd.id);
213:       else if (cmd.status === 'done') completeQuest(cmd.id);
214:       return true;
215:     case 'key':
216:       if (!state.inventory[cmd.item]) {
217:         addItem(cmd.item, 1);
218:         toast(`${ITEMS[cmd.item]?.name || 'Key'} claimed.`, '✧', 3800);
219:         audio.sfx('levelup');
220:       }
221:       state.flags[cmd.flag] = true;
222:       countKeys();
223:       syncHud();
224:       saveGame(true);
225:       return true;
226:     case 'act':
227:       syncHud();
228:       return true;
229:     case 'hud':
230:       updateHud(currentZone());
231:       return true;
232:     case 'save':
233:       saveGame(true);
234:       return true;
235:     case 'ending':
236:       return await finishEnding(cmd.id, ctx);
237:     default:
238:       console.warn('Unknown story command', cmd);
239:       return undefined;
240:   }
241: }
