757: async function finishBattle(raw) {
758:   battleState.phase = 'end';
759:   const diff = DIFFICULTY[state.settings?.difficulty] || DIFFICULTY.balanced;
760:   let result = raw || { victory: false };
761:   if (result.victory) {
762:     let xp = 0, gold = 0;
763:     const drops = [];
764:     for (const e of battleState.enemies) {
765:       const def = e.def;
766:       xp += Math.round((def.xp || 10) * (1 + (e.level - 1) * .17) * diff.xp);
767:       gold += Math.round((def.gold || 5) * (1 + (e.level - 1) * .12));
768:       if (def.drop && !def.noDrop) {
769:         const chance = def.boss ? 1 : (def.drop.chance || .1);
770:         if (Math.random() < chance) {
771:           const item = ITEMS[def.drop.item];
772:           if (item?.type === 'gear') addGear(def.drop.item);
773:           else addItem(def.drop.item, 1);
774:           drops.push(item?.name || def.drop.item);
775:         }
776:       }
777:     }
778:     addGold(gold);
779:     const levels = [];
780:     for (const m of state.party) {
781:       const gained = addXp(m, xp);
782:       if (gained.length) levels.push({ name: m.name, level: m.level });
783:     }
784:     if (state.quests?.bounty?.status === 'active' && battleState.zone?.id === 'emberfield') {
785:       state.quests.bounty.kills += battleState.enemies.length;
786:       pushLog(`Bounty tally: ${state.quests.bounty.kills} / 6.`, 'good');
787:     }
788:     syncMembers();
789:     result = { ...result, xp, gold, drops, levels };
790:     pushLog('Victory. The ash settles.', 'good');
791:     battleState.result = result;
792:     audio.sfx('victory');
793:     if (levels.length) setTimeout(() => audio.sfx('levelup'), 380);
794:     saveGame(true);
795:   } else if (result.defeat) {
796:     audio.sfx('defeat');
797:     const lost = Math.floor((state.gold || 0) * .1);
798:     state.gold = Math.max(0, (state.gold || 0) - lost);
799:     const fallen = battleState.allies.filter((a) => a.dead).map((a) => a.name);
800:     restoreParty(true);
801:     syncMembers();
802:     result = { ...result, goldLost: lost, fallen };
803:     battleState.result = result;
804:     saveGame(true);
805:   } else if (result.fled) {
806:     result = { ...result, victory: false, fled: true };
807:     battleState.result = result;
808:     syncMembers();
809:   }
810:   uiBattle.syncBattleUI();
811:   await uiBattle.showBattleResult(result, battleState);
812:   battleState.active = false;
813:   battleState.phase = 'idle';
814:   battleState.activeUid = null;
815:   battleState.targetUid = null;
816:   uiBattle.hideBattleUI();
817:   audio.setScene(sceneForZone(battleState.zone));
818:   saveGame(true);
819:   return result;
820: }
